"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[61248],{68489:e=>{e.exports=JSON.parse('{"tag":{"label":"behavior","permalink":"/docs/tags/behavior","allTagsPath":"/docs/tags","count":17,"items":[{"id":"Rabbits/getting-started/essential-supplies-for-rabbits","title":"essential-supplies-for-rabbits","description":"Bringing a rabbit into your home is a long-term commitment, and providing the right supplies is the first step to ensuring a happy, healthy life for your new friend. Rabbits have specific needs that...","permalink":"/docs/Rabbits/getting-started/essential-supplies-for-rabbits"},{"id":"general-care/daily-care/is-my-pet-nocturnal","title":"is-my-pet-nocturnal","description":"Learn the difference between nocturnal, diurnal, and crepuscular activity patterns and find out when your small pet is naturally most active. Understanding their sleep cycle is key to providing the best care.","permalink":"/docs/general-care/daily-care/is-my-pet-nocturnal"},{"id":"Rats/care-and-husbandry/playing-and-training","title":"playing-and-training","description":"A guide to playing with and training your pet rats, offering ideas for enrichment, toys, and teaching simple tricks to engage their intelligence.","permalink":"/docs/Rats/care-and-husbandry/playing-and-training"},{"id":"Rats/getting-started/rat-care-guide","title":"rat-care-guide","description":"Rat Behavior Guide","permalink":"/docs/Rats/getting-started/rat-care-guide"},{"id":"Rats/health-and-wellness/rat-introductions","title":"rat-introductions","description":"Introducing a new rat to your existing group (or \'mischief\') is an exciting step, but it must be handled with care and patience. Rats are territorial and have complex social hierarchies. A proper...","permalink":"/docs/Rats/health-and-wellness/rat-introductions"},{"id":"Rats/breeds-and-genetics/rat-variety-guide","title":"rat-variety-guide","description":"Welcome to the colorful world of fancy rats! Through selective breeding, pet rats have been developed in a stunning array of colors, coat types, and markings. While these varieties are fascinating,...","permalink":"/docs/Rats/breeds-and-genetics/rat-variety-guide"},{"id":"general-care/daily-care/socializing-your-small-pet","title":"socializing-your-small-pet","description":"A guide to socializing and building trust with timid small pets like rabbits, guinea pigs, and rodents, using patience and positive reinforcement to create a strong bond.","permalink":"/docs/general-care/daily-care/socializing-your-small-pet"},{"id":"Chinchillas/health-and-wellness/understanding-chinchilla-behavior","title":"understanding-chinchilla-behavior","description":"Chinchillas are active, curious animals with a surprisingly rich behavioral repertoire. They are crepuscular \u2014 most active at dawn and dusk \u2014 and can live for 15 years or more.","permalink":"/docs/Chinchillas/health-and-wellness/understanding-chinchilla-behavior"},{"id":"Degus/health-and-wellness/understanding-degu-behavior","title":"understanding-degu-behavior","description":"Degus are highly social, intelligent, and vocal rodents from Chile, often described as having the curiosity of a rat and the social complexity of a prairie dog...","permalink":"/docs/Degus/health-and-wellness/understanding-degu-behavior"},{"id":"Ferrets/health-and-wellness/understanding-ferret-behavior","title":"understanding-ferret-behavior","description":"Ferrets are playful, mischievous, and highly social animals with a personality that is often described as a cross between a cat and a dog. Understanding their unique behaviors is key to a happy, healthy ferret.","permalink":"/docs/Ferrets/health-and-wellness/understanding-ferret-behavior"},{"id":"Gerbils/health-and-wellness/understanding-gerbil-behavior","title":"understanding-gerbil-behavior","description":"Gerbils are highly social, curious animals that communicate through a combination of body language, scent marking, and vocalizations.","permalink":"/docs/Gerbils/health-and-wellness/understanding-gerbil-behavior"},{"id":"guinea-pigs/health-and-wellness/understanding-guinea-pig-behavior","title":"understanding-guinea-pig-behavior","description":"Guinea pigs are highly vocal, social animals with a rich repertoire of sounds and body language. Learning to read their cues is one of the most rewarding parts of guinea pig ownership.","permalink":"/docs/guinea-pigs/health-and-wellness/understanding-guinea-pig-behavior"},{"id":"Hamsters/health-and-wellness/understanding-hamster-behavior","title":"understanding-hamster-behavior","description":"Hamsters are solitary, nocturnal animals with a fascinating range of behaviors. Learning to read their body language is essential for building trust and keeping them healthy.","permalink":"/docs/Hamsters/health-and-wellness/understanding-hamster-behavior"},{"id":"Hedgehogs/health-and-wellness/understanding-hedgehog-behavior","title":"understanding-hedgehog-behavior","description":"Hedgehogs are unique and fascinating creatures with a set of behaviors all their own. As solitary and nocturnal animals, their communication is often quiet and defensive...","permalink":"/docs/Hedgehogs/health-and-wellness/understanding-hedgehog-behavior"},{"id":"Mice/health-and-wellness/understanding-mouse-behavior","title":"understanding-mouse-behavior","description":"Mice are intelligent, curious, and surprisingly complex little animals. While often quiet, they have a rich system of communication based on body language, scent, and ultrasonic sounds...","permalink":"/docs/Mice/health-and-wellness/understanding-mouse-behavior"},{"id":"Rabbits/health-and-wellness/understanding-rabbit-behavior","title":"understanding-rabbit-behavior","description":"Rabbits are highly expressive animals whose body language is subtle but rich. Understanding what your rabbit is communicating is key to building a trusting relationship and catching health problems early.","permalink":"/docs/Rabbits/health-and-wellness/understanding-rabbit-behavior"},{"id":"Rats/health-and-wellness/understanding-rat-behavior","title":"understanding-rat-behavior","description":"Rats are intelligent, social, and emotionally complex animals. Understanding their natural behaviors and unique ways of communicating is key to building a strong bond and providing them with the best...","permalink":"/docs/Rats/health-and-wellness/understanding-rat-behavior"}],"unlisted":false}}')}}]);